/// The public half of the account's key, as the provider needs it. Never a private
/// key.
class AccountPublicMaterial {
  const AccountPublicMaterial({
    required this.algorithm,
    required this.keyFingerprint,
    this.publicKeyJwk,
    this.certificatePem,
    this.address,
    this.pendingKeyFingerprint,
  });

  /// Read this payload from a decoded JSON object.
  factory AccountPublicMaterial.fromJson(Map<String, dynamic> json) =>
      AccountPublicMaterial(
        algorithm: AccountPublicMaterialAlgorithm(json['algorithm'] as String),
        keyFingerprint: json['keyFingerprint'] as String,
        publicKeyJwk: json['publicKeyJwk'] == null
            ? null
            : AccountPublicMaterialPublicKeyJwk.fromJson(
                json['publicKeyJwk'] as Map<String, dynamic>),
        certificatePem: json['certificatePem'] as String?,
        address: json['address'] as String?,
        pendingKeyFingerprint: json['pendingKeyFingerprint'] as String?,
      );

  final AccountPublicMaterialAlgorithm algorithm;

  /// Digest of the public key's SubjectPublicKeyInfo DER.
  final DigestMultibase keyFingerprint;

  /// The public key as a JWK, with `kid`. Public members only: the schema admits no
  /// private member (`d`, `p`, `q`, `dp`, `dq`, `qi`), so a document carrying one fails
  /// validation.
  final AccountPublicMaterialPublicKeyJwk? publicKeyJwk;

  /// `aws-roles-anywhere`: the trust anchor's CA certificate. `azure-cert`: the
