/// An account as every read returns it. Contains no private key, no secret and no
/// issued credential, to any reader.
class ExternalAccount {
  const ExternalAccount({
    required this.id,
    required this.label,
    required this.context,
    required this.settings,
    required this.state,
    this.publicMaterial,
    this.secret,
    required this.bindings,
    required this.egressHosts,
    required this.providerSetupRequired,
    this.lastProbe,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory ExternalAccount.fromJson(Map<String, dynamic> json) =>
      ExternalAccount(
        id: json['id'] as String,
        label: json['label'] as String,
        context: json['context'] as String,
        settings: json['settings'],
        state: AccountState(json['state'] as String),
        publicMaterial: json['publicMaterial'] == null
            ? null
            : AccountPublicMaterial.fromJson(
                json['publicMaterial'] as Map<String, dynamic>),
        secret: json['secret'] == null
            ? null
            : AccountSecretInfo.fromJson(
                json['secret'] as Map<String, dynamic>),
        bindings: (json['bindings'] as List<dynamic>)
            .map((e) => AccountBinding.fromJson(e as Map<String, dynamic>))
            .toList(),
        egressHosts: (json['egressHosts'] as List<dynamic>)
            .map((e) => e as String)
            .toList(),
        providerSetupRequired: json['providerSetupRequired'] as bool,
        lastProbe: json['lastProbe'] == null
            ? null
            : AccountProbeReport.fromJson(
                json['lastProbe'] as Map<String, dynamic>),
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
      );

  final AccountId id;

  /// Display name. Untrusted text: render it, never interpret it.
  final String label;
  final AccountContextId context;
  final AccountSettings settings;
  final AccountState state;

  /// Absent for the static models, which hold a secret rather than a key.
  final AccountPublicMaterial? publicMaterial;

  /// Static models only; absent until the secret is set.
  final AccountSecretInfo? secret;
  final List<AccountBinding> bindings;

  /// The provider hosts this account's use connects to, derived by the custodian from
  /// its settings. The custodian MUST NOT connect anywhere else on this account's
  /// behalf, so an egress proxy can allow exactly this set. Empty for models that need
  /// no egress.
  final List<String> egressHosts;

  /// True when the account cannot be used until its provider-side setup is redone: after
  /// a restore that could not carry its key or secret (a wrapped RSA key, a static
  /// secret), or after a rotation awaiting confirmation.
  final bool providerSetupRequired;
  final AccountProbeReport? lastProbe;
  final String createdAt;
  final String updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'id': id,
        'label': label,
        'context': context,
        'settings': settings,
        'state': state.value,
        if (publicMaterial != null) 'publicMaterial': publicMaterial!.toJson(),
        if (secret != null) 'secret': secret!.toJson(),
        'bindings': bindings.map((e) => e.toJson()).toList(),
        'egressHosts': egressHosts,
        'providerSetupRequired': providerSetupRequired,
        if (lastProbe != null) 'lastProbe': lastProbe!.toJson(),
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}

